import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  const group = new Group();
  group.position.fromArray(config.scenePosition || [0, 0.7, 0]);
  group.rotation.order = 'YXZ';

  // Plane geometry for the list row
  const geometry = new PlaneGeometry(3.0, 0.35, 1, 1);

  // Load the brushed metal texture
  let material;
  const materialPromise = config.imageUrl
    ? ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
        material.map = tex;
        material.needsUpdate = true;
      })
    : Promise.resolve();

  // Create material with tsl nodes for subtle gradient/effect
  const uvNode = uv();
  const timeNode = time;

  // Subtle animated opacity based on position for a divider-like effect
  const dividerStrength = smoothstep(0.45, 0.55, uvNode.y);
  const colorNode = mix(
    vec3(0.086, 0.086, 0.063),   // surface #0b0b10
    vec3(0.906, 0.925, 0.949),   // paper #e8ecf2
    dividerStrength
  );

  material = new MeshBasicNodeMaterial({
    colorNode,
    transparent: true,
    depthWrite: false,
    side: ctx.THREE.DoubleSide,
  });

  const plane = new Mesh(geometry, material);
  group.add(plane);

  // State for interaction
  let isHovered = false;
  let pressTimeline = null;

  // Handler: hover
  const onHoverEnter = () => {
    if (isHovered) return;
    isHovered = true;

    gsap.killTweensOf(group.position);
    gsap.to(group.position, {
      y: group.position.y + 0.15,
      duration: 0.5,
      ease: 'power3.out',
      overwrite: 'auto',
    });
  };

  const onHoverExit = () => {
    if (!isHovered) return;
    isHovered = false;

    gsap.killTweensOf(group.position);
    gsap.to(group.position, {
      y: config.scenePosition?.[1] || 0.7,
      duration: 0.5,
      ease: 'power3.out',
      overwrite: 'auto',
    });
  };

  // Handler: click
  const onClick = () => {
    // Press-down scale effect
    gsap.killTweensOf(group.scale);
    gsap.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out',
      overwrite: 'auto',
    });

    // Settle back to 1.0
    gsap.to(group.scale, {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.9,
      ease: 'power4.out',
      delay: 0.12,
      overwrite: 'auto',
    });

    // Emit selection event
    ctx.emit('hub-collection.select', { nodeId: config.id });
  };

  // Attach handlers
  group.userData.handlers = {
    onHoverEnter,
    onHoverExit,
    onClick,
  };

  // Cleanup
  group.userData.cleanup = () => {
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    geometry.dispose();
    material.dispose();
    materialPromise.then(() => {
      if (material.map) material.map.dispose();
    });
  };

  return group;
}
